  def genTestSuite(testCases: ISZ[(Z, ISZ[ST])]): Unit = {
    val tq = "\"\"\""

    val testRoot = Os.path(".") / "src" / "test" / "bridge"

    val Fault_Assessment_supervisor_fa_id = Arch.Mining_Threat_Retreat_Supervisor_Root_Instance_supervisor_fa.id
    val Threat_Qualification_supervisor_tq_id = Arch.Mining_Threat_Retreat_Supervisor_Root_Instance_supervisor_tq.id
    val Resource_Qualification_supervisor_rq_id = Arch.Mining_Threat_Retreat_Supervisor_Root_Instance_supervisor_rq.id
