    val Atomic_Publication_supervisor_ap_id = Arch.Mining_Threat_Retreat_Supervisor_Root_Instance_supervisor_ap.id

    def genUniqueSuiteName(path: Os.Path, prefix: String): String = {
      var i = 0
      while(true) {
        val cand = path / s"${prefix}_${i}.scala"
        if (!cand.exists) {
          return s"${prefix}_${i}"
        }
        i = i + 1
      }
      halt("Infeasible")
    }

    for (p <- testCases) {
      art.Art.BridgeId.fromZ(p._1) match {
        case Fault_Assessment_supervisor_fa_id =>
          val prefix = "Fault_Assessment_supervisor_fa_RM_TestSuite"
          val path = testRoot /+ ISZ("scp_candidate","Mining_Threat_Retreat_Supervisor")
          val suiteName = genUniqueSuiteName(path, prefix)

          val testSuite =
            st"""package scp_candidate.Mining_Threat_Retreat_Supervisor
                |
                |import org.sireum._
                |import scp_candidate.Mining_Threat_Retreat_Supervisor._
                |
                |class ${suiteName} extends Fault_Assessment_supervisor_fa_ScalaTest {
                |  val verbose: B = T
                |
                |  ${p._2}
                |}"""
          val filename = path / s"${suiteName}.scala"
          filename.writeOver(testSuite.render)
          println(s"Wrote: ${filename.toUri}")
        case Threat_Qualification_supervisor_tq_id =>
          val prefix = "Threat_Qualification_supervisor_tq_RM_TestSuite"
          val path = testRoot /+ ISZ("scp_candidate","Mining_Threat_Retreat_Supervisor")
